using System.Text.Json;
using Mono.Cecil;
using Mono.Cecil.Cil;
var input=JsonDocument.Parse(File.ReadAllText(args[0]));
var modules=input.RootElement.GetProperty("modules").EnumerateArray().Select(x=>ModuleDefinition.ReadModule(x.GetString()!)).ToArray();
IEnumerable<TypeDefinition> Walk(IEnumerable<TypeDefinition> types){foreach(var type in types){yield return type;foreach(var nested in Walk(type.NestedTypes))yield return nested;}}
var rows=new List<object>();var seen=new HashSet<string>();
foreach(var site in input.RootElement.GetProperty("sites").EnumerateArray())
{
    var module=modules.Single(m=>m.Mvid==Guid.Parse(site.GetProperty("mvid").GetString()!));
    var typeName=site.GetProperty("type").GetString()!.Split("[[")[0].Replace('+','/');
    var type=Walk(module.Types).Single(t=>t.FullName==typeName);
    var display=site.GetProperty("method").GetString()!;var name=display.Split('(')[0].Split(' ',2)[1].Split('[')[0];
    var methods=type.Methods.Where(m=>m.Name==name).ToArray();if(methods.Length==0)throw new InvalidOperationException(typeName+":"+display);
    foreach(var method in methods)
    {
        if(!seen.Add(module.Mvid+":"+method.FullName))continue;
        rows.Add(new{module=module.Name,mvid=module.Mvid,definition=method.FullName,method.IsStatic,method.IsVirtual,method.IsConstructor,
            instructions=method.HasBody?method.Body.Instructions.Select(i=>new{offset=i.Offset,opcode=i.OpCode.Name,operand=i.Operand?.ToString()}).ToArray():[],
            directTargets=method.HasBody?method.Body.Instructions.Where(i=>i.Operand is MethodReference).Select(i=>((MethodReference)i.Operand).FullName).ToArray():[]});
    }
}
File.WriteAllText(args[1],JsonSerializer.Serialize(new{rows,definitions=rows.Count,scope="Actual definition IL for observed native sites; overload candidates are included, constructed generic substitution remains in native evidence. No invocation or whole effect certificate."},new JsonSerializerOptions{WriteIndented=true}));
foreach(var module in modules)module.Dispose();
Console.WriteLine("METADATA_DEFINITIONS "+rows.Count);
